def extract_readme_description(project_root: Path) -> str:
    """Extract a single-line summary from the project's README.md for GitHub (author case kept)."""
    readme = project_root / "README.md"
    if not readme.is_file():
        return ""
    try:
        content = readme.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""
    desc_lines: List[str] = []
    has_header = any(line.strip().startswith("#") for line in content.splitlines())
    past_header = not has_header
    for line in content.splitlines():
        stripped = line.strip()
        if not past_header:
            if stripped.startswith("#"):
                past_header = True
            continue
        if not stripped:
            if desc_lines:
                break
            continue
        if stripped.startswith("#"):
            break
        clean = _clean_markdown_line(stripped)
        if clean:
            desc_lines.append(clean)
    text = " ".join(desc_lines).strip()
    # GitHub holds 350 characters; the 200 used before cut what `new --description` accepts (ADR-202).
    return (text[:347].rstrip() + "...") if len(text) > 350 else text

